FROM public.hk_census_2021_cell c
JOIN public.hk_census_2021_geography g ON c.district_code = g.district_code
WHERE c.release_id = 'dc2021-f099e9b34408' AND g.geography_kind = 'district'
GROUP BY g.district_code, g.district_name, g.region) SELECT s.*, json_build_object('type','Feature','geometry',b.geometry::json,'properties',json_build_object('fillColor',CASE WHEN population<200000 THEN '#c6dbef' WHEN population<350000 THEN '#9ecae1' WHEN population<500000 THEN '#6baed6' WHEN population<650000 THEN '#3182bd' ELSE '#08519c' END,'strokeColor','#ffffff'),'extraProps',json_build_object('District / 地區 / 地区',s.district_name || ' · ' || g.district_name_zh,'Population / 人口',to_char(population,'FM999,999,999'),'Age 65+ / 65歲及以上 / 65岁及以上',to_char(elderly_share_percent,'FM990.0') || '%','Household income / 住戶收入 / 住户收入','HK$' || to_char(median_household_income_hkd,'FM999,999,999')))::text AS geojson FROM summary s JOIN boundaries b USING (district_code) JOIN public.hk_census_2021_geography g USING (district_code)
